// Access the input data objects provided to the tool node
const weatherData = $('OpenWeatherMap').item.json;

const temp = weatherData.main.temp;
const feelsLike = weatherData.main.feels_like;
const description = weatherData.weather[0].description;
const humidity = weatherData.main.humidity;

// Returns a clean structured text format for the AI model to interpret
return `Current Weather conditions: ${description}. Temperature: ${temp}°C. Feels like: ${feelsLike}°C. Humidity: ${humidity}%.`;

const items = $input.all();

for (const item of items) {
  const query = item.json.city || '';

  let city = query
    // Remove common filler words/phrases
    .replace(/current weather/gi, '')
    .replace(/weather (in|for|at)?/gi, '')
    .replace(/(today|tomorrow|now|forecast|please)/gi, '')
    .replace(/[^a-zA-Z\s]/g, '') // strip punctuation/numbers
    .trim();

  item.json.city = city;
}

return items;
